    Source: packages/compose-gen/specs/organisms/lightbox-stage.json
    The selected photo in a dialog: title, close, picture, optional caption and previous/next. Static open state. Used by LightboxGallery.
    Props (p): photos, labels, captions, lightbox. *}
{var $v_photos = ($p['photos'] ?? null)}
{var $v_labels = ($p['labels'] ?? null)}
{var $v_captions = ($p['captions'] ?? 'show')}
{var $v_lightbox = ($p['lightbox'] ?? 'closed')}
{capture $c_10}
  {capture $c_3}
    {capture $c_1}
      {=og_text(og_first_of($v_photos, 'title'))}
    {/capture}
    {=og_include('compose/Text.latte', ['size' => 'sm', 'weight' => 'semibold', 'children' => (string) $c_1])|noescape}
    {capture $c_2}
      {=og_include('icons/LucideIcon.latte', ['name' => 'x', 'size' => 16])|noescape}
    {/capture}
    {=og_include('compose/Button.latte', ['variant' => 'ghost', 'size' => 'sm', 'layout' => 'icon', 'type' => 'button', 'ariaLabel' => og_s(og_get($v_labels, ['close'])), 'children' => (string) $c_2])|noescape}
  {/capture}
  {=og_include('compose/Group.latte', ['gap' => '2', 'align' => 'center', 'justify' => 'between', 'children' => (string) $c_3])|noescape}
  {=og_include('blocks/media-frame.latte', ['p' => ['alt' => og_first_of($v_photos, 'title'), 'ratio' => '4/3']])|noescape}
  {if og_t(og_eq($v_captions, 'show'))}
    {capture $c_4}
      {=og_text(og_first_of($v_photos, 'tag'))}
    {/capture}
    {=og_include('compose/Text.latte', ['size' => 'sm', 'class' => 'text-muted-foreground', 'children' => (string) $c_4])|noescape}
  {/if}
  {capture $c_9}
    {capture $c_5}
      {=og_text(og_tpl(og_get($v_labels, ['counter']), [1, og_len($v_photos)]))}
    {/capture}
    {=og_include('compose/Text.latte', ['size' => 'xs', 'class' => 'text-muted-foreground', 'children' => (string) $c_5])|noescape}
    {capture $c_8}
      {capture $c_6}
        {=og_include('icons/LucideIcon.latte', ['name' => 'chevron-left', 'size' => 16])|noescape}
      {/capture}
      {=og_include('compose/Button.latte', ['variant' => 'outline', 'size' => 'sm', 'layout' => 'icon', 'type' => 'button', 'ariaLabel' => og_s(og_get($v_labels, ['previous'])), 'children' => (string) $c_6])|noescape}
      {capture $c_7}
        {=og_include('icons/LucideIcon.latte', ['name' => 'chevron-right', 'size' => 16])|noescape}
      {/capture}
      {=og_include('compose/Button.latte', ['variant' => 'outline', 'size' => 'sm', 'layout' => 'icon', 'type' => 'button', 'ariaLabel' => og_s(og_get($v_labels, ['next'])), 'children' => (string) $c_7])|noescape}
    {/capture}
    {=og_include('compose/Group.latte', ['gap' => '2', 'children' => (string) $c_8])|noescape}
  {/capture}
  {=og_include('compose/Group.latte', ['gap' => '2', 'align' => 'center', 'justify' => 'between', 'children' => (string) $c_9])|noescape}
{/capture}
{=og_include('compose/Dialog.latte', ['open' => og_t(og_eq($v_lightbox, 'open')), 'size' => 'xl', 'ariaLabel' => og_s(og_first_of($v_photos, 'title')), 'class' => 'gap-4 p-4', 'attrs' => og_attrs(['data-slot', 'lightbox']), 'children' => (string) $c_10])|noescape}
